local KEY_SYSTEM_URL = "https://github.com/adubwon/nex/raw/refs/heads/main/voidhub/key.lua"

local function verifyAndLoadScript()
    local success, scriptSource = pcall(function()
        return game:HttpGet(KEY_SYSTEM_URL, true)
    end)
    
    if not success then
        error("Failed to fetch script: " .. tostring(scriptSource))
    end
    
    if not scriptSource or #scriptSource < 10 then
        error("Empty script content")
    end
    
    local compiledScript = loadstring(scriptSource)
    if not compiledScript then
        error("Failed to compile script")
    end
    
    return compiledScript()
end

pcall(verifyAndLoadScript)

